// ClusterServiceClient is a client for the hotbed.v1.ClusterService service.
type ClusterServiceClient interface {
	// Join admits the calling tailnet node as a worker.
	Join(context.Context, *v1.JoinRequest) (*v1.JoinResponse, error)
	// Report is how workers before the event stream accounted for
	// themselves: their whole state, which the controller took as the node's
	// view. The controller still takes it until every worker pushes events.
	Report(context.Context, *v1.ReportRequest) (*v1.ReportResponse, error)
	// PushEvents delivers a worker's events, in order, from after what the
	// controller has applied; or a checkpoint of its state when the
	// controller cannot continue from what it has.
	PushEvents(context.Context, *v1.PushEventsRequest) (*v1.PushEventsResponse, error)
	// Heartbeat is a worker's live usage, lossy: the latest wins. It keeps
	// the node online, and its reply is what the worker should host.
	Heartbeat(context.Context, *v1.HeartbeatRequest) (*v1.HeartbeatResponse, error)
	ListNodes(context.Context, *v1.ListNodesRequest) (*v1.ListNodesResponse, error)
	// GetBuild is the build the controller runs, for a platform: what a node
	// or client on it installs to run the controller's build.
	GetBuild(context.Context, *v1.GetBuildRequest) (*v1.Build, error)
	// UpgradeController checks CI for a newer build immediately, installs it
	// over the controller, and restarts the controller as it.
	UpgradeController(context.Context, *v1.UpgradeControllerRequest) (*v1.UpgradeControllerResponse, error)
	ListRepos(context.Context, *v1.ListReposRequest) (*v1.ListReposResponse, error)
	PutRepo(context.Context, *v1.PutRepoRequest) (*v1.Repo, error)
	DeleteRepo(context.Context, *v1.DeleteRepoRequest) (*v1.DeleteRepoResponse, error)
	// RebuildRepo has every worker build the repo's next base from nothing.
	// Bases are otherwise built incrementally: each generation forks the one
	// before, pulls, and freshens.
	RebuildRepo(context.Context, *v1.RebuildRepoRequest) (*v1.Repo, error)
	// PutStep adds a setup step to a repo, or replaces the one of that name.
	// The next workspace of the repo gets a base that has run it.
	PutStep(context.Context, *v1.PutStepRequest) (*v1.Repo, error)
	DeleteStep(context.Context, *v1.DeleteStepRequest) (*v1.Repo, error)
	// ListSteps is a repo's steps and, for each, whether each node's newest
	// base has run it.
	ListSteps(context.Context, *v1.ListStepsRequest) (*v1.ListStepsResponse, error)
	// AddProject creates a project, or adds repos to the one of that name. A
	// repo another project holds is refused unless shared: sessions starting
	// in its checkouts would then have to name their project.
	AddProject(context.Context, *v1.AddProjectRequest) (*v1.Project, error)
	// RemoveProjectRepos takes repos out of a project.
	RemoveProjectRepos(context.Context, *v1.RemoveProjectReposRequest) (*v1.Project, error)
	ListProjects(context.Context, *v1.ListProjectsRequest) (*v1.ListProjectsResponse, error)
	// GetProject is a project with every change made to it.
	GetProject(context.Context, *v1.GetProjectRequest) (*v1.Project, error)
	// GetSnapshot is everything the cockpit shows.
	GetSnapshot(context.Context, *v1.GetSnapshotRequest) (*v1.Snapshot, error)
}

